<?php session_start(); require 'conectare.php'; $id=filter_input(INPUT_GET,'id_domeniu',FILTER_VALIDATE_INT) ?: 0; $s=$pdo->prepare('SELECT nume_domeniu FROM domenii WHERE id_domeniu=?'); $s->execute([$id]); $domain=$s->fetch(); if(!$domain){http_response_code(404);exit('Domeniu inexistent.');} $s=$pdo->prepare('SELECT c.id_carte,c.titlu,a.nume_autor,c.pret FROM carti c JOIN autori a ON a.id_autor=c.id_autor WHERE c.id_domeniu=? ORDER BY c.titlu'); $s->execute([$id]); $books=$s->fetchAll(); include 'page_top.php'; include 'meniu.php'; ?>
